# coding: utf-8
"""Make the user-requested partial metric the report entry point; retain strict results."""
import subprocess,sys,json
from pathlib import Path
HERE=Path(__file__).resolve().parent;ROOT=HERE.parents[2];OUT=ROOT/'docs/situation-goal100'
for script in ['report.py','partial_report.py']:subprocess.run([sys.executable,str(HERE/script)],check=True,stdout=subprocess.DEVNULL)
strict=(OUT/'README.md').read_text();(OUT/'COMPLETE-SET-DETAILS.md').write_text(strict)
full=json.loads((OUT/'summary.json').read_text());partial=json.loads((OUT/'partial-summary.json').read_text());assert partial['complete'] and partial['common_evaluated_cases']==100
p=partial['common_case_summary'];a=p['hybrid'];b=p['llm_full_catalog'];sa=full['summary']['hybrid'];sb=full['summary']['llm_full_catalog'];pct=lambda x:f'{100*x:.2f}%'
lines=['# 상황형 복합 요청 100문항 — 부분 적중률 비교','', '사용자가 승인한 상황 추천 기준으로 새 100문항을 실행했다. 실행 도중 사용자 요청으로 부분 적중률을 주 지표로 추가했다. 모델·질문·허용 정답을 변경하거나 점수를 높이기 위해 다시 호출하지 않았다. 완전일치 결과도 별도로 보존했다.', '', '**부분 적중**: 추천 결과에 사전 허용 정답 메뉴(승인한 선택 추천 포함)가 하나라도 있으면 성공이다. 틀린 메뉴가 함께 있어도 적중이 되므로, 추천 수·허용 메뉴 비율·필수 업무 포함률을 반드시 함께 본다.', '', '| 지표 | LLM→E5→JEV | GPT-4.1 단독 |','|---|---:|---:|',f"| 부분 적중률 | **{a['partial_hit_correct']}/100 · {pct(a['partial_hit_rate'])}** | **{b['partial_hit_correct']}/100 · {pct(b['partial_hit_rate'])}** |",f"| 추천 메뉴 중 허용 메뉴 비율 | {pct(a['menu_level_allowed_precision'])} | {pct(b['menu_level_allowed_precision'])} |",f"| 문항당 추천 메뉴 수 | {a['mean_recommended_menus']:.2f}개 | {b['mean_recommended_menus']:.2f}개 |",f"| 필수 업무 Recall (문항별 평균) | {pct(a['macro_required_outcome_recall'])} | {pct(b['macro_required_outcome_recall'])} |",f"| 일부 적중 + 비허용 메뉴 없음 | {a['partial_with_no_disallowed_correct']}/100 | {b['partial_with_no_disallowed_correct']}/100 |",f"| 허용 전체 조합+상태 완전일치 | {sa['accepted_set_correct']}/100 | {sb['accepted_set_correct']}/100 |",f"| 평균 / P95 HTTP ms | {sa['mean_all_ms']:,.2f} / {sa['p95_all_ms']:,.2f} | {sb['mean_all_ms']:,.2f} / {sb['p95_all_ms']:,.2f} |",f"| 문항당 입력 / 출력 토큰 | {sa['input_mean']:,.2f} / {sa['output_mean']:,.2f} | {sb['input_mean']:,.2f} / {sb['output_mean']:,.2f} |",f"| 캐시 반영 API 비용 추정 /100문항 | ${sa['cost_usd']:.4f} | ${sb['cost_usd']:.4f} |",f"| 캐시 없이 환산한 비용 /100문항 | ${sa['no_cache_cost_usd']:.4f} | ${sb['no_cache_cost_usd']:.4f} |",f"| 오류(부분 적중 실패 포함) | {sa['errors']} | {sb['errors']} |", '', '## 상황별 부분 적중','', '| 상황(각 10개 표현) | 삼단계 | 단독 LLM |','|---|---:|---:|']
for f,x in partial['family_results']['hybrid'].items():
 title=full['family_results']['hybrid'][f]['title'];y=partial['family_results']['llm_full_catalog'][f];lines.append(f"| {title} | {x['partial_hit_correct']}/10 | {y['partial_hit_correct']}/10 |")
lines+=['','## 읽을 때 주의할 점','', '- 100개의 서로 다른 표현이지만 **10개 승인 상황군 ×10개 표현**이다. 100개 독립 상황, 전문가 독립 검수, 실사용 전체 정확도가 아니다. 목표만 주는 50개와 상황·제약을 주는 50개로 구성했다.', '- 부분 적중률은 여러 업무를 모두 해결했다는 의미가 아니다. 승인한 선택 추천 하나만 맞아도 부분 적중이 될 수 있다. 필요한 업무 누락과 허용 밖 메뉴는 별도 수치로 남긴다.', '- 단독 LLM과 삼단계의 추천 수가 다르다. 더 많이 제시하면 부분 적중률이 높아질 수 있으므로 메뉴 적합 비율과 추천 수를 함께 비교해야 한다. 같은 첫 1/2/3개 응답 예산의 진단 수치는 partial-summary.json에 있다. 출력 순서는 전역 관련도 순위를 보장하지 않는다.', '- 이전 95% 실험과 평가셋·정답 기준이 다르다. 기존 수치와 개선율로 직접 비교하지 않는다. 이번 부분 지표도 사용자 요청으로 실행 도중 추가한 것이며 사전 고정 지표였다고 표현하지 않는다.', '- 두 경로는 동일 GPT-4.1과 동일 585개 메뉴를 사용한다. 단독은 ID·이름·설명, 삼단계는 업무 분해 후 실제 E5 후보와 JEV 선택을 사용한다. JEV에는 후보의 select_when도 있어 모든 상세 입력 필드가 동일한 실험은 아니다.', '- HTTP 시간은 실제 요청 중 모델·검색·proxy를 포함하며 큐 대기·컴파일·모델 기동은 제외한다. 오류도 전체 평균에 포함했다. 각 조건 1회이며 네트워크·캐시·모델 변동성이 있다.', '- 한도 오류만 교체하고 그 시도는 비교 토큰에서 제외한다는 사용자 지시를 적용했다. 오류에 usage가 없으면 0으로 만들지 않는다. 모델·형식·정확도 오류는 재실행하지 않았다.', '- 비용은 관측 usage와 공개 표준단가의 추정이며 전체 청구액이 아니다. 캐시 입력은 입력의 일부이고 JEV 출력은 무료다. 로컬 E5 CPU/호스팅·세금·계정별 요금 차이·개발 및 제외 시도는 빠져 있다.', '- 발표 페이지 구성은 취소 상태로 유지했고 GitHub에도 게시하지 않았다.', '', '완전일치 및 상세 실패: COMPLETE-SET-DETAILS.md / failures.json. 실제 응답: run/results.json. 부분 지표: partial-summary.json. 비용: summary.json 및 unit-prices.json. 단가 출처: [OpenAI 공식 모델 문서](https://developers.openai.com/api/docs/models/gpt-4.1), [TypeSafe 공식 요금 안내](https://help.typesafe.ai/articles/5187202169-how-much-does-jev-cost).']
(OUT/'README.md').write_text('\n'.join(lines)+'\n');print('Finalized user-requested partial report; strict outcomes retained')
